// Text for the page scripts: /i18n/<lang>.js (generated by the server from lutetia/web/i18n.py) sets window.LUTETIA_I18N first.
// T('key', { name: value }) fills {name} placeholders. A missing dictionary or key is logged loudly and the key is shown, never hidden.
(function () {
  'use strict';
  var dict = window.LUTETIA_I18N;
  if (!dict) {
    console.error('i18n dictionary missing: /i18n/<lang>.js did not load');
    dict = {};
  }
  window.T = function (key, vars) {
    var text = dict[key];
    if (text === undefined) {
      console.error('i18n key missing', key);
      return key;
    }
    return text.replace(/\{(\w+)\}/g, function (m, name) {
      return vars && Object.prototype.hasOwnProperty.call(vars, name) ? vars[name] : m;
    });
  };
})();
